from datetime import date, datetime, timedelta
from zoneinfo import ZoneInfo

PIECES = "social_content_pieces"
TYPES = {"social_post": "Social media post", "article": "Article", "email": "Email", "announcement": "Announcement", "visual": "Visual"}
CHANNELS = {"instagram": "Instagram", "facebook": "Facebook", "linkedin": "LinkedIn", "google_business": "Google Business", "email": "Email", "website": "Website", "print": "Print"}
NEWLINE = chr(10)


def text(value):
    if value is None:
        return ""
    if isinstance(value, (list, tuple)):
        return ", ".join(str(v) for v in value)
    return str(value).strip()


settings = api.extension.settings() or {}
zone = ZoneInfo(text(settings.get("time_zone")) or "Australia/Sydney")
today = datetime.now(zone).date()
monday = today - timedelta(days=today.weekday())
sunday = monday + timedelta(days=6)

# Every content piece, a page at a time (a small business has tens, not thousands).
rows = []
cursor = None
for _ in range(10):
    page = api.records.list(type_slug=PIECES, limit=200, cursor=cursor) or {}
    rows.extend(page.get("records") or [])
    cursor = page.get("nextCursor")
    if not cursor:
        break

week = []
for row in rows:
    data = row.get("data") or {}
    raw = text(data.get("publish_date"))[:10]
    try:
        when = date.fromisoformat(raw)
    except ValueError:
        continue
    if not (monday <= when <= sunday):
        continue
    if text(data.get("knowledge_path")):
        state = "approved, saved to Knowledge (" + text(data.get("knowledge_path")) + ")"
    elif text(data.get("origin")) == "campaign" and data.get("generate_draft") is False:
        state = "calendar only: the team writes this one"
    elif text(data.get("check_summary")):
        state = "drafted, waiting for review"
    else:
        state = "not drafted yet"
    channels = ", ".join(CHANNELS.get(c, c) for c in (data.get("channels") or []) if isinstance(c, str))
    kind = TYPES.get(text(data.get("content_type")), "Content")
    title = text(row.get("title") or data.get("piece_title")) or "Untitled piece"
    week.append((when, title, kind, channels, state))
week.sort(key=lambda w: (w[0], w[1]))

piece_count = len(week)
todo_id = ""
notice_title = "Publishing this week: " + monday.strftime("%d/%m") + " to " + sunday.strftime("%d/%m/%Y")
if piece_count:
    lines = ["These pieces are due to be published this week. Nothing is posted for you: post each one on its day, then tick its \"Post it today\" task.", ""]
    for when, title, kind, channels, state in week:
        lines.append("- **" + when.strftime("%a %d/%m") + "**: " + title + " (" + kind + (", " + channels if channels else "") + "), " + state)
    waiting = len([w for w in week if w[4] == "drafted, waiting for review"])
    if waiting:
        lines.extend(["", str(waiting) + " still need your review: open Agents > Social Media Agent > Needs your attention."])
    body = NEWLINE.join(lines)
    existing = [t for t in (api.workq.list(search=notice_title) or []) if text(t.get("title")) == notice_title]
    if existing:
        todo_id = text(existing[0].get("id"))
        api.workq.update(todo_id=todo_id, description=body)
    else:
        made = api.workq.create(title=notice_title, scope="org", description=body, due_date=monday.isoformat(), labels=["social-media-agent"])
        todo_id = text((made or {}).get("id"))
